-- 981_state_exec_seed_batch_b.sql
-- Phase 141 (v2.18 State Leaders), plan 141-04.
-- GENERATED by backend/scripts/gen-state-exec-seed.mjs from live-verified (June 2026) roster.
-- Seeds 35 in-scope elected Big-5 offices across: AR, GA, HI, IA, MO, ND, OK, VT.
-- Idempotent (NOT EXISTS / ON CONFLICT guards). external_id = -(fips*100000+seq) except AK/AZ collision offsets.
-- Run: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f backend/migrations/981_state_exec_seed_batch_b.sql

BEGIN;

